homio_entity.extra_styles:
:host {
  scroll-margin-inline: 8vw;
  /* Beat button-card inline --button-card-ripple-color (HA light amber). */
  --button-card-ripple-color: rgba(255,255,255,0.45) !important;
  --button-card-ripple-hover-color: rgba(255,255,255,0.45) !important;
  --button-card-ripple-pressed-color: rgba(255,255,255,0.45) !important;
  --button-card-light-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-hover-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-pressed-color: rgba(255,255,255,0.45) !important;
}
/* button-card defaults name/state to centered text; keep left once width is 100%. */
#name, #state, #label {
  text-align: left !important;
  justify-content: start !important;
  justify-self: start !important;
}
ha-card {
  --ha-ripple-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-hover-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-pressed-color: rgba(255,255,255,0.45) !important;
  --button-card-ripple-color: rgba(255,255,255,0.45) !important;
  filter: none !important;
  -webkit-filter: none !important;
}
/* Sticky :hover after slider/hold — kill filter cast on all pointers. */
ha-card:hover,
ha-card:active,
ha-card:focus {
  filter: none !important;
  -webkit-filter: none !important;
  box-shadow: none !important;
  outline: none !important;
  --ha-ripple-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-hover-color: rgba(255,255,255,0.45) !important;
  --ha-ripple-pressed-color: rgba(255,255,255,0.45) !important;
  --button-card-ripple-color: rgba(255,255,255,0.45) !important;
}
:host([data-homio-chrome-drag]) ha-card,
:host([data-homio-chrome-drag]) ha-card:hover,
:host([data-homio-chrome-drag]) ha-card:active {
  filter: none !important;
  -webkit-filter: none !important;
  box-shadow: none !important;
  --ha-ripple-hover-opacity: 0 !important;
  --ha-ripple-pressed-opacity: 0 !important;
  --mdc-ripple-hover-opacity: 0 !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host([data-homio-chrome-drag]) ha-card > ha-ripple {
  opacity: 0 !important;
  pointer-events: none !important;
}
/* Nested chrome: suppress parent ripple while nested controls are pressed.
   #temperature_controls is inside a nested button-card shadow tree, so parent
   must key off #target_temperature. Hover suppress is desktop-only — iOS
   sticky :hover would otherwise leave the parent dead after a nested tap.
   Touch: data-homio-nested-press is set by www/homio-entity-strip.js because
   :active does not cross nested button-card shadows on iOS. */
:host([data-homio-nested-press]) ha-card {
  --ha-ripple-hover-opacity: 0 !important;
  --ha-ripple-pressed-opacity: 0 !important;
  --mdc-ripple-hover-opacity: 0 !important;
  --mdc-ripple-press-opacity: 0 !important;
  filter: none !important;
  box-shadow: none !important;
}
:host([data-homio-nested-press]) ha-card > ha-ripple {
  opacity: 0 !important;
  pointer-events: none !important;
}
ha-card:has(#light-slider:active),
ha-card:has(#heating_modes:active),
ha-card:has(#target_temperature:active) {
  --ha-ripple-hover-opacity: 0 !important;
  --ha-ripple-pressed-opacity: 0 !important;
  --mdc-ripple-hover-opacity: 0 !important;
  --mdc-ripple-press-opacity: 0 !important;
  filter: none !important;
  box-shadow: none !important;
}
ha-card:has(#light-slider:active) > ha-ripple,
ha-card:has(#heating_modes:active) > ha-ripple,
ha-card:has(#target_temperature:active) > ha-ripple {
  opacity: 0 !important;
  pointer-events: none !important;
}
@media (hover: hover) {
  ha-card:has(#light-slider:hover),
  ha-card:has(#heating_modes:hover),
  ha-card:has(#target_temperature:hover) {
    --ha-ripple-hover-opacity: 0 !important;
    --ha-ripple-pressed-opacity: 0 !important;
    --mdc-ripple-hover-opacity: 0 !important;
    --mdc-ripple-press-opacity: 0 !important;
    filter: none !important;
    box-shadow: none !important;
  }
  ha-card:has(#light-slider:hover) > ha-ripple,
  ha-card:has(#heating_modes:hover) > ha-ripple,
  ha-card:has(#target_temperature:hover) > ha-ripple {
    opacity: 0 !important;
    pointer-events: none !important;
  }
}

